static SDL_AudioDeviceID audioDev;
static int optMaster = 8, optMusic = 6, optTurn = 5, optSplit = 0, optFull = 1, optAim = 2, optEasy = 0;
static volatile int musicMode;          /* 0 calm, 1 wave in progress */
static double musClock;
static float padPh[6], padLp, bassPh, bassEnv, bassF, melPh, melEnv, melF, hatEnv, windLp, windLp2, windT;
static int musStep = -1;
static const int chordRoot[4] = {45, 41, 38, 40};
static const int chordPad[4][3] = {{57, 60, 64}, {53, 57, 60}, {50, 53, 57}, {52, 56, 59}};
static const int melody[32] = {76, 0, 72, 0, 69, 0, 71, 72, 72, 0, 69, 0, 65, 0, 0, 0, 74, 0, 72, 0, 69, 0, 65, 0, 68, 0, 71, 0, 76, 0, 0, 0};
static float midiHz(int n) { return 440.f * powf(2.f, (n - 69) / 12.f); }
static float padF[6];
static void audioCb(void *ud, Uint8 *stream, int len)
{
    (void)ud;
    Sint16 *out = (Sint16 *)stream;
    int n = len / 2;
    float mv = optMaster / 10.f, muv = mv * optMusic / 10.f;
    double stepLen = SR * 60.0 / 84.0 / 2.0;
    for (int i = 0; i < n; i++) {
        float s = 0.f;
        for (int v = 0; v < 24; v++) {
            Voice *vo = &voices[v];
            if (vo->dur <= 0.f) continue;
            if (vo->delay > 0.f) { vo->delay -= 1.f / SR; continue; }
            float u = vo->t / vo->dur;
            if (u >= 1.f) { vo->dur = 0.f; continue; }
            float x = 0.f;
            if (vo->type == V_NOISE) {
                float r = frand() * 2.f - 1.f;
                vo->lp += (r - vo->lp) * vo->k;
                float e = 1.f - u; x = vo->lp * e * e * 2.f;
            } else if (vo->type == V_TONE) {
                float f = vo->f0 + (vo->f1 - vo->f0) * u;
                vo->ph += f / SR; vo->ph -= floorf(vo->ph);
                x = (vo->ph < 0.5f ? 0.5f : -0.5f) * (1.f - u);
            } else {
                float f = vo->f0 * (1.f + 0.07f * sinf(vo->t * 31.f));
                vo->ph += f / SR; vo->ph -= floorf(vo->ph);
                vo->lp += ((vo->ph * 2.f - 1.f) - vo->lp) * 0.08f;
                x = vo->lp * sinf(u * PI_F) * 1.6f;
            }
            s += x * vo->vol;
            vo->t += 1.f / SR;
        }
        s *= mv;
        /* music */
        int step = (int)(musClock / stepLen);
        if (step != musStep) {
            musStep = step;
            int chord = (step / 8) % 4;
            for (int k = 0; k < 3; k++) { padF[k * 2] = midiHz(chordPad[chord][k]); padF[k * 2 + 1] = padF[k * 2] * 1.006f; }
            int m = melody[step % 32];
            if (m && (musicMode == 1 || (step / 32) % 2 == 0)) { melF = midiHz(m); melEnv = 1.f; }
            if (musicMode == 1 && step % 2 == 0) { bassF = midiHz(chordRoot[chord] + ((step / 2) % 2 ? 12 : 0)); bassEnv = 1.f; }
            if (musicMode == 1) hatEnv = (step % 2) ? 0.6f : 1.f;
        }
        musClock += 1.0;
        float m = 0.f;
        for (int k = 0; k < 6; k++) { padPh[k] += padF[k] / SR; padPh[k] -= floorf(padPh[k]); m += padPh[k] * 2.f - 1.f; }
        padLp += (m - padLp) * 0.03f;
        float out1 = padLp * 0.05f;
        melPh += melF / SR; melPh -= floorf(melPh);
        out1 += sinf(melPh * 2.f * PI_F) * melEnv * 0.13f; melEnv *= 0.99982f;
        bassPh += bassF / SR; bassPh -= floorf(bassPh);
        out1 += (fabsf(bassPh * 4.f - 2.f) - 1.f) * bassEnv * 0.2f; bassEnv *= 0.99975f;
        out1 += (frand() * 2.f - 1.f) * hatEnv * 0.03f; hatEnv *= 0.994f;
        s += out1 * muv;
        /* wind */
        windT += 1.f / SR;
        float k = 0.012f + 0.01f * sinf(windT * 0.21f);
        windLp += ((frand() * 2.f - 1.f) - windLp) * k;
        windLp2 += (windLp - windLp2) * k;
        s += windLp2 * (0.35f + 0.25f * sinf(windT * 0.37f)) * 0.5f * mv;
        s = clampf(s, -1.f, 1.f);
        out[i] = (Sint16)(s * 26000.f);
    }
}
static void playV(int type, float dur, float f0, float f1, float vol, float k, float delay)
{
    if (!audioDev) return;
    SDL_LockAudioDevice(audioDev);
    int best = 0; float bestLeft = 1e9f;
    for (int v = 0; v < 24; v++) {
        if (voices[v].dur <= 0.f) { best = v; break; }
        float left = voices[v].dur - voices[v].t;
        if (left < bestLeft) { bestLeft = left; best = v; }
    }
    Voice *vo = &voices[best];
    vo->type = type; vo->t = 0.f; vo->dur = dur; vo->f0 = f0; vo->f1 = f1; vo->vol = vol; vo->ph = 0.f; vo->lp = 0.f; vo->k = k; vo->delay = delay;
    SDL_UnlockAudioDevice(audioDev);
}
static void sndDeny(void) { playV(V_TONE, 0.2f, 160, 110, 0.35f, 0, 0); }
static void sndBuy(void) { playV(V_TONE, 0.12f, 660, 990, 0.3f, 0, 0); playV(V_TONE, 0.18f, 990, 1320, 0.3f, 0, 0.1f); }
static void sndRoundStart(void)
{
    playV(V_TONE, 0.45f, 220, 218, 0.4f, 0, 0.0f);
    playV(V_TONE, 0.45f, 207, 205, 0.4f, 0, 0.5f);
    playV(V_TONE, 1.10f, 165, 150, 0.45f, 0, 1.0f);
    playV(V_NOISE, 1.2f, 0, 0, 0.25f, 0.02f, 1.0f);
}
static void sndRoundEnd(void)
{
    playV(V_TONE, 0.3f, 196, 196, 0.35f, 0, 0.0f);
    playV(V_TONE, 0.3f, 247, 247, 0.35f, 0, 0.3f);
    playV(V_TONE, 0.8f, 294, 290, 0.4f, 0, 0.6f);
}

